import java.util.Arrays;
import java.util.Random;

public class Bench {
    static final int CUTOFF = 7;
    // previous recursive version (with same cutoff) for comparison
    static void rec(int[] a, int[] buf, int lo, int hi) {
        if (hi - lo + 1 <= CUTOFF) { ins(a, lo, hi); return; }
        int mid = lo + (hi - lo) / 2;
        rec(a, buf, lo, mid); rec(a, buf, mid + 1, hi);
        System.arraycopy(a, lo, buf, lo, hi - lo + 1);
        int l = lo, r = mid + 1;
        for (int d = lo; d <= hi; d++) {
            if (l > mid) a[d] = buf[r++]; else if (r > hi) a[d] = buf[l++];
            else if (buf[l] <= buf[r]) a[d] = buf[l++]; else a[d] = buf[r++];
        }
    }
    static void ins(int[] a, int lo, int hi) {
        for (int i = lo + 1; i <= hi; i++) { int k = a[i], j = i - 1;
            while (j >= lo && a[j] > k) { a[j+1] = a[j]; j--; } a[j+1] = k; }
    }
    static void recursive(int[] a) { if (a != null && a.length > 1) rec(a, new int[a.length], 0, a.length - 1); }
    static long time(Runnable r, int reps){ long b=Long.MAX_VALUE; for(int i=0;i<reps;i++){long t=System.nanoTime();r.run();b=Math.min(b,System.nanoTime()-t);} return b; }

    public static void main(String[] x) {
        // large-n correctness for bottom-up
        Random rnd = new Random(99);
        int[] big = new int[5_000_000];
        for (int i = 0; i < big.length; i++) big[i] = rnd.nextInt();
        int[] exp = big.clone(); Arrays.sort(exp);
        int[] got = big.clone(); MergeSort.sort(got);
        System.out.println("large-n (5M) correct: " + Arrays.equals(got, exp));

        int n = 2_000_000, trials = 8;
        int[] base = new int[n];
        for (int i = 0; i < n; i++) base[i] = rnd.nextInt();
        for (int w = 0; w < 5; w++){ int[] c=base.clone(); MergeSort.sort(c); int[] d=base.clone(); recursive(d); }
        long bu = time(() -> { int[] c = base.clone(); MergeSort.sort(c); }, trials);
        long re = time(() -> { int[] c = base.clone(); recursive(c); }, trials);
        System.out.printf("n=%d (best of %d)%n", n, trials);
        System.out.printf("  recursive (prev): %6.1f ms%n", re / 1e6);
        System.out.printf("  bottom-up (new) : %6.1f ms%n", bu / 1e6);
        System.out.printf("  ratio           : %.2fx%n", (double) re / bu);
    }
}
